.cm {font-family:var(--font-sans);-webkit-font-smoothing:antialiased;letter-spacing:var(--tracking-snug);box-sizing:border-box;--sh-composer:0 3px 8px rgb(0 0 0/.09),0 2px 5px rgb(0 0 0/.09),0 1px 1px rgb(0 0 0/.1);position:relative;border-radius:var(--radius-lg);background:var(--composer-surface,var(--color-card));padding:12px;box-shadow:var(--sh-composer);width:100%}
:where([data-doop-theme="light"]) .cm {--sh-composer:0 4px 12px rgb(0 0 0/.025),0 2px 6px rgb(0 0 0/.03),0 1px 1px rgb(0 0 0/.04);}
.cm .edge {pointer-events:none;position:absolute;inset:0;border-radius:var(--radius-lg);border:var(--spacing-hairline) solid transparent;background:linear-gradient(180deg,var(--color-border-2),var(--color-border-1)) border-box;-webkit-mask:linear-gradient(#000,#000) padding-box,linear-gradient(#000,#000) border-box;-webkit-mask-composite:xor;mask-composite:exclude}
.cm .fld {position:relative;min-height:64px;max-height:224px;padding:4px;font-size:var(--text-base);font-weight:var(--font-weight-normal);color:var(--color-foreground);letter-spacing:var(--tracking-tight)}
.cm .ph {color:var(--color-muted-foreground-3)}
.cm .tb {margin:0 -4px -4px;display:flex;align-items:center;gap:8px;padding-top:4px}
.cm .lft {display:flex;min-width:0;flex:1;align-items:center;gap:2px}
.cm .ib, .cm .snd {display:inline-flex;width:var(--spacing-control-sm);height:var(--spacing-control-sm);align-items:center;justify-content:center;border-radius:var(--radius-md);color:var(--color-muted-foreground-1);cursor:pointer;transition:color 100ms,background-color 100ms;border:var(--spacing-hairline) solid transparent;box-sizing:border-box}
.cm .ib:hover {color:var(--color-foreground);background:var(--color-secondary)}
.cm svg {width:var(--spacing-icon-sm);height:var(--spacing-icon-sm);flex-shrink:0}
.cm .mp {margin-left:4px;display:inline-flex;height:var(--spacing-control-sm);align-items:center;gap:6px;padding:0 8px;border-radius:var(--radius-md);font-size:var(--text-xs);font-weight:var(--font-weight-medium);color:var(--color-muted-foreground-1);cursor:pointer;transition:color 100ms,background-color 100ms}
.cm .mp:hover {color:var(--color-foreground);background:var(--color-secondary)}
.cm .mi {display:flex;margin-left:-2px;color:var(--color-primary-ink)}
.cm .ef {color:var(--color-muted-foreground-2)}
.cm .mc {display:flex;margin-right:-2px;color:var(--color-muted-foreground-3)}
.cm .snd {background:var(--color-primary);border-color:color-mix(in oklch,var(--color-primary) 80%,black);color:var(--color-primary-foreground);box-shadow:inset 0 1px oklch(1 0 0/.12),0 .5px 1px 1px rgb(0 0 0/.3)}
.cm .snd:hover {background:color-mix(in oklch,var(--color-primary) 92%,black)}
